func testLLMDecisionRunToManyRemoveOpDecisionRunLLMBudgetReservations(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a LLMDecisionRun
	var b, c, d, e LLMBudgetReservation

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, llmDecisionRunDBTypes, false, strmangle.SetComplement(llmDecisionRunPrimaryKeyColumns, llmDecisionRunColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*LLMBudgetReservation{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, llmBudgetReservationDBTypes, false, strmangle.SetComplement(llmBudgetReservationPrimaryKeyColumns, llmBudgetReservationColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddDecisionRunLLMBudgetReservations(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.DecisionRunLLMBudgetReservations().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveDecisionRunLLMBudgetReservations(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.DecisionRunLLMBudgetReservations().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.DecisionRunID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.DecisionRunID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.DecisionRun != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.DecisionRun != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.DecisionRun != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.DecisionRun != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.DecisionRunLLMBudgetReservations) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.DecisionRunLLMBudgetReservations[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.DecisionRunLLMBudgetReservations[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

