func testLLMDecisionRunToOneLLMMarketSnapshotUsingSnapshot(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local LLMDecisionRun
	var foreign LLMMarketSnapshot

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, llmDecisionRunDBTypes, true, llmDecisionRunColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize LLMDecisionRun struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, llmMarketSnapshotDBTypes, false, llmMarketSnapshotColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize LLMMarketSnapshot struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.SnapshotID, foreign.ID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.Snapshot().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.ID, foreign.ID) {
		t.Errorf("want: %v, got %v", foreign.ID, check.ID)
	}

	slice := LLMDecisionRunSlice{&local}
	if err = local.L.LoadSnapshot(ctx, tx, false, (*[]*LLMDecisionRun)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Snapshot == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.Snapshot = nil
	if err = local.L.LoadSnapshot(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.Snapshot == nil {
		t.Error("struct should have been eager loaded")
	}
}

